#!/usr/bin/env python3
"""immuno/bcr_seq_lineage — auto-generated run.py (archetype=mhc_epitope).

第一版只实现 simulate 模式:从 stdin/args 拿 inputs,产合理合成数据 JSON。
真实现路径(simulate=False)留 stub:返回 not-implemented + 提示。

输入契约:
  stdin JSON,字段按 SKILL.md 的 inputs 段;simulate 默认 true。
  CLI 兜底:--simulate / 各位置参数。

输出:
  stdout JSON;失败时也写 JSON {"ok": false, "error": "..."} 而非裸 traceback。
"""
import json
import sys

ARCHETYPE = "mhc_epitope"
BRAIN = "immuno"
SKILL = "bcr_seq_lineage"

def simulate(payload):
    """auto-generated by regen_simulate.py — outputs schema 来自 SKILL.md."""
    import copy
    import random
    random.seed(int(payload.get("seed", 42)) if isinstance(payload, dict) else 42)
    out = copy.deepcopy({'clones': [], 'lineage_trees': [{'clone_id': 'C0001', 'newick': '(...)', 'root_germline_v': 'IGHV1-69', 'members': [{'seq_id': '...', 'timepoint': 'd28', 'shm_count': 14, 'isotype': 'IgG1'}]}], 'shm_distribution': {'mean': 12.4, 'p95': 28}, 'baselineselection_per_clone': {'C0001': {'pi_cdr': 0.32, 'pi_fr': -0.08}}, 'aid_motif_enrichment': {'WRC': 0.63, 'WGCW': 0.21}, 'isotype_switching_events': [{'clone': 'C0001', 'from': 'IgM', 'to': 'IgG1'}]})
    if isinstance(out, dict):
        out.setdefault("diagnostics", {})
        if isinstance(out["diagnostics"], dict):
            out["diagnostics"].update({
                "simulated": True,
                "archetype": ARCHETYPE,
                "brain": BRAIN,
                "skill": SKILL,
            })
        if "skill_id" in out and not out["skill_id"]:
            out["skill_id"] = SKILL
    return out

def real(payload):
    """BCR sequence ANARCI numbering + germline 距离(简化 lineage)。host_env=antibody。"""
    import os as _os
    import tempfile as _tempfile
    import time as _time
    try:
        from brains._common.lib.run_tool import run_tool
    except ImportError:
        import sys as _sys
        _sys.path.insert(0, "/home/zkyd/data1/mzy/praxis2-brains")
        from _common.lib.run_tool import run_tool  # noqa: F401
    seqs = payload.get("sequences") or ([payload.get("sequence")] if payload.get("sequence") else [])
    scheme = payload.get("scheme", "imgt")  # imgt | kabat | chothia | aho
    out_dir = payload.get("out_dir") or _tempfile.mkdtemp(prefix="anarci_")
    diagnostics = {"brain": BRAIN, "skill": SKILL, "archetype": ARCHETYPE,
                   "tool": "ANARCI", "scheme": scheme, "out_dir": out_dir}
    if _os.environ.get("PRAXIS_SKILL_DRY_HOST") == "1":
        return {"ok": True, "skill_id": SKILL, "n_epitopes": 0, "epitopes_csv": "",
                "diagnostics": {**diagnostics, "dry": True}}
    if not seqs:
        return {"ok": False, "error": "需要 sequence(s)", "diagnostics": diagnostics}
    fa = _os.path.join(out_dir, "input.fa")
    _os.makedirs(out_dir, exist_ok=True)
    with open(fa, "w") as fh:
        for i, s in enumerate(seqs):
            fh.write(f">seq_{i}\n{s}\n")
    out_anarci = _os.path.join(out_dir, "anarci.txt")
    t0 = _time.time()
    r = run_tool(["ANARCI", "-i", fa, "-o", out_anarci, "-s", scheme, "--csv"],
                 timeout=int(payload.get("timeout_s", 600)))
    diagnostics["subprocess"] = {"wall_sec": r.get("wall_sec"), "rc": r.get("returncode")}
    if not r["ok"]:
        return {"ok": False, "error": r.get("error", "ANARCI 失败"),
                "stderr": r.get("stderr", "")[-300:], "diagnostics": diagnostics}
    import glob as _glob
    csvs = sorted(_glob.glob(out_anarci + "*"))
    return {"ok": True, "skill_id": SKILL,
            "n_epitopes": len(seqs), "epitopes_csv": csvs[0] if csvs else out_anarci,
            "anarci_files": csvs,
            "runtime_sec": round(_time.time() - t0, 2), "diagnostics": diagnostics}

def main():
    # stdin 优先(SkillExecTool 走 stdin)
    payload = {}
    if not sys.stdin.isatty():
        try:
            payload = json.load(sys.stdin)
            if not isinstance(payload, dict):
                payload = {}
        except json.JSONDecodeError:
            payload = {}
    if not payload:
        # 简易 CLI 兜底
        import argparse
        ap = argparse.ArgumentParser()
        ap.add_argument("--simulate", action="store_true", default=True)
        ap.add_argument("--seed", type=int, default=42)
        args, _ = ap.parse_known_args()
        payload = {"simulate": args.simulate, "seed": args.seed}

    simulate_mode = bool(payload.get("simulate", True))
    try:
        out = simulate(payload) if simulate_mode else real(payload)
    except Exception as e:
        out = {"ok": False, "error": f"run.py 内部错误: {e!r}"}

    if isinstance(out, dict):
        out.setdefault("diagnostics", {})
        if isinstance(out["diagnostics"], dict):
            out["diagnostics"].update({"archetype": ARCHETYPE, "brain": BRAIN, "skill": SKILL})
    json.dump(out, sys.stdout, ensure_ascii=False)
    sys.stdout.write("\n")
    return 0

if __name__ == "__main__":
    sys.exit(main())
